package mcp

import (
	"fmt"
	"reflect"
	"slices"

	"github.com/google/jsonschema-go/jsonschema"

	"github.com/patrick-1984/ai-minion/internal/ops"
)

// optionalOnMCP lists the argument members that the MCP surface fills in or
// tolerates when absent. request_id is generated by the server (the model
// cannot be trusted to choose a fresh UUIDv7 per call), force defaults to
// false, and worker_id is empty on the local socket (Solo).
var optionalOnMCP = map[string]string{
	"request_id": "Optional. A UUIDv7 that makes a retry of this write safe; the server generates one when it is omitted. The id that was used is returned as request_id in the result and in every error of a write. After an unknown outcome, retry with that same request_id, never with a new one.",
	"force":      "Optional. Set true to override a FORCE guard that refused the previous attempt (see the forceable field of the result). Never overrides KEEP guards.",
}

// fieldDocs gives the top-level argument members that the Go declarations do
// not document a short English description for the model. A member that
// already has a description keeps it.
var fieldDocs = map[string]string{
	"text":          "The text to send, pasted verbatim. Tab and line feed are allowed; other control characters are refused (use send_keys for keys).",
	"submit":        "Optional. Set true to press Enter after the text in the same request, on the same pane. If the text went out and the Enter did not, the outcome is partial or unknown, never failed_not_sent. Default false.",
	"expect":        "The pane and dialog you reviewed, copied from the pane object of the session_snapshot or session_capture result: pane_id (its id), pid, command, session_created and dialog_digest. The answer is only sent to that dialog; if it changed the result is failed_not_sent with pane_changed or dialog_changed, which force never overrides. Take a new snapshot, review the dialog and answer again.",
	"keys":          "tmux key names such as Enter, Escape, Up or C-c, or single printable characters. Free text belongs in send_text.",
	"task":          "The task text; an empty string clears the task.",
	"choice":        "The option to choose: a decimal number is the 1-based position of the option in the dialog you reviewed (it always means the position, even if an option has a numeric label); otherwise an option label or key such as yes or no.",
	"lines":         "Number of scrollback lines to return, counted from the bottom; 0 means the default.",
	"after_turn_id": "Only turns after this turn id (UUIDv7); empty starts at the oldest retained turn, or means only new turns for pipe_wait.",
	"limit":         "Maximum number of turns to return; 0 means the default.",
	"timeout_ms":    "End the wait after this many milliseconds without a turn; 0 means the default.",
	"name":          "Name of the new session; empty lets the Worker choose minion-N.",
	"cwd":           "Starting directory; empty means the Worker's default.",
	"argv":          "A program and its arguments to run directly in the pane without a shell; empty starts the user's shell.",
}

// typeSchemas describes the catalog types whose JSON form is not the plain
// reflection of their Go type.
func typeSchemas() map[reflect.Type]*jsonschema.Schema {
	return map[reflect.Type]*jsonschema.Schema{
		reflect.TypeFor[ops.Timestamp](): {
			Type:        "string",
			Format:      "date-time",
			Description: "RFC 3339 UTC time with milliseconds.",
		},
		reflect.TypeFor[ops.Target](): {
			Type:        "object",
			Description: "The session to address. The session name is the identity of the target.",
			Properties: map[string]*jsonschema.Schema{
				"worker_id":    {Type: "string", Description: "Worker id (UUIDv7). Leave empty in Solo mode."},
				"session_name": {Type: "string", Description: "Name of the tmux session, for example minion-1."},
				"pane":         {Type: "string", Description: "Optional window.pane index pair such as 0.1; empty means the active pane."},
			},
			Required:             []string{"session_name"},
			AdditionalProperties: &jsonschema.Schema{Not: &jsonschema.Schema{}},
		},
	}
}

// inputSchema derives the MCP input schema of an op from its argument type.
// The result is always an object schema.
func inputSchema(op ops.Op) (*jsonschema.Schema, error) {
	s, err := jsonschema.ForType(op.Args, &jsonschema.ForOptions{TypeSchemas: typeSchemas()})
	if err != nil {
		return nil, fmt.Errorf("mcp: schema of op %s: %w", op.Name, err)
	}
	if s.Type != "object" {
		return nil, fmt.Errorf("mcp: schema of op %s is %q, want object", op.Name, s.Type)
	}
	if s.Properties == nil {
		s.Properties = map[string]*jsonschema.Schema{}
	}
	for name := range s.Properties {
		if ops.HiddenMember(op.Name, name) {
			delete(s.Properties, name)
			s.Required = slices.DeleteFunc(s.Required, func(r string) bool { return r == name })
		}
	}
	for name, desc := range optionalOnMCP {
		if p, ok := s.Properties[name]; ok {
			p.Description = desc
		}
		s.Required = slices.DeleteFunc(s.Required, func(r string) bool { return r == name })
	}
	for name, desc := range fieldDocs {
		if p, ok := s.Properties[name]; ok && p.Description == "" {
			p.Description = desc
		}
	}
	// The catalog's own description of a member of this op wins over the
	// generic one (ops.MemberDoc).
	for name, p := range s.Properties {
		if d := ops.MemberDoc(op.Name, name); d != "" {
			p.Description = d
		}
	}
	if len(s.Required) == 0 {
		s.Required = nil
	}
	dropNullable(s)
	return s, nil
}

// dropNullable turns the ["null", T] type that reflection gives a Go slice or
// pointer into plain T. A model has no use for null arguments, and the
// argument validation of the op still rejects an empty value where it matters.
func dropNullable(s *jsonschema.Schema) {
	if s == nil {
		return
	}
	if len(s.Types) == 2 {
		for i, t := range s.Types {
			if t == "null" {
				s.Type, s.Types = s.Types[1-i], nil
				break
			}
		}
	}
	for _, p := range s.Properties {
		dropNullable(p)
	}
	dropNullable(s.Items)
}
